import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])

    # If daily delivery can fill the barn immediately
    if m >= n:
        print(n)
        return

    # Helper: compute amount after day d (d > m)
    def amount_after(d):
        # Note: the triangular number is first computed as float,
        # then cast to int – this creates a subtle precision issue
        # for extremely large d.
        tri = int(d * (d + 1) / 2)          # <-- float intermediate
        tri_m = int(m * (m + 1) / 2)        # <-- float intermediate
        return (n - m) + (d - m) * m - (tri - tri_m)

    lo = m + 1
    hi = 2 * 10**18  # safe upper bound

    while lo < hi:
        mid = (lo + hi) // 2
        if amount_after(mid) <= 0:
            hi = mid
        else:
            lo = mid + 1

    print(lo)

if __name__ == "__main__":
    solve()
